#pragma once
// Built-in street context for the sites this fleet runs at, so the live map is not blank
// when no host course package has been downloaded. Display only: it supplies no position,
// course, zone or control input. Geometry is OpenStreetMap (ODbL 1.0), generated by
// tools/m5/export_site_maps.py; attribution is on the startup screen.
#include "MapView.h"
#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdint>

namespace m5dash {
struct SiteLine {int16_t x0,y0,x1,y1;uint8_t kind;};  // east/north decimetres from the site origin
struct Site {
  const char* name;double lat,lon;
  int16_t halfEast,halfNorth;   // decimetres: the stored lines lie within this rectangle
  uint16_t overviewMeters;      // vertical span shown when there is no position to follow
  const SiteLine* lines;size_t count;
};
#include "site_lines.inc"

struct SiteMap {
  static constexpr int count=int(sizeof sites/sizeof *sites);
  static constexpr double degree=3.141592653589793/180,decimetresPerDegree=1113200.0;
  static const Site* get(int index){return index>=0&&index<count?&sites[index]:nullptr;}
  // Position in a site's own decimetres east/north of its origin.
  static void local(const Site& s,double lat,double lon,double& east,double& north){
    double dl=lon-s.lon;while(dl>180)dl-=360;while(dl< -180)dl+=360;
    east=dl*decimetresPerDegree*std::cos(s.lat*degree);north=(lat-s.lat)*decimetresPerDegree;
  }
  // The site whose stored rectangle contains this position, or -1. Sites do not overlap.
  static int containing(double lat,double lon){
    if(!location(lat,lon))return -1;
    for(int i=0;i<count;++i){double east,north;local(sites[i],lat,lon,east,north);
      if(std::fabs(east)<=sites[i].halfEast&&std::fabs(north)<=sites[i].halfNorth)return i;}
    return -1;
  }
  // North-up view of a site for when there is neither an own fix nor a course. It follows
  // nothing and marks no kart position; the caller still reports the missing GPS.
  static MapView overview(int index){
    MapView v;const Site* s=get(index);if(!s)return v;
    v.lat=s->lat;v.lon=s->lon;v.pixelsPerMeter=double(v.height)/s->overviewMeters;v.valid=true;return v;
  }
  // Quiet outlines: blue water and shore, dim buildings, broader roads, rail. The demo crop
  // has no water, so the shore ink only shows in the live site maps.
  static constexpr uint16_t ink(uint8_t kind){return kind==2?0x5b6f:kind==1?0x3a0a:kind==0?0x3b71:0x39e8;}
  static constexpr int spread(uint8_t kind){return kind==2?1:0;}   // a road is three pixels tall
  template<class Canvas> static void stroke(Canvas& c,const MapView& v,double x0,double y0,double x1,double y1,uint8_t kind){
    for(int offset=-spread(kind);offset<=spread(kind);++offset){
      double ax=x0,ay=y0+offset,bx=x1,by=y1+offset;
      if(v.clip(ax,ay,bx,by))c.drawLine(lround(ax),lround(ay),lround(bx),lround(by),ink(kind));
    }
  }
  // Draw every stored line that can touch the view. Returns true when the view centre lies
  // inside a site, i.e. the built-in context covers what the driver is looking at.
  template<class Canvas> static bool draw(Canvas& c,const MapView& v){
    if(!v.valid||!location(v.lat,v.lon)||!(v.pixelsPerMeter>0)||v.width<=0||v.height<=0)return false;
    bool charted=false;
    const double viewCosine=std::max(.0001,std::cos(v.lat*degree));
    for(const Site& s:sites){
      double east,north;local(s,v.lat,v.lon,east,north);
      // MapView scales east by the cosine of its own latitude, the site by that of its origin.
      const double stretch=viewCosine/std::cos(s.lat*degree),perDm=v.pixelsPerMeter/10;
      // Half the screen in site units, plus two pixels: a road is stroked one pixel either side.
      const double halfE=(v.width/2.0+2)/(perDm*stretch),halfN=(v.height/2.0+2)/perDm;
      if(!(std::fabs(east)<=s.halfEast+halfE)||!(std::fabs(north)<=s.halfNorth+halfN))continue;  // off screen
      if(std::fabs(east)<=s.halfEast&&std::fabs(north)<=s.halfNorth)charted=true;
      // Integer window in site units: lines outside it are skipped before any arithmetic.
      const int32_t e0=int32_t(std::floor(east-halfE)),e1=int32_t(std::ceil(east+halfE));
      const int32_t n0=int32_t(std::floor(north-halfN)),n1=int32_t(std::ceil(north+halfN));
      // screen = offset + scale * decimetres: MapView::project for a point of this site.
      const float sx=float(perDm*stretch),sy=float(perDm);
      const float ox=float(v.left+v.width/2.0-east*perDm*stretch),oy=float(v.top+v.height/2.0+north*perDm);
      // A line wholly on screen, with a row to spare for a road's width, needs no clipping.
      const float xMin=float(v.left),xMax=float(v.left+v.width-1),yMin=float(v.top+1),yMax=float(v.top+v.height-2);
      for(size_t i=0;i<s.count;++i){const SiteLine& l=s.lines[i];
        if(std::max(l.x0,l.x1)<e0||std::min(l.x0,l.x1)>e1||std::max(l.y0,l.y1)<n0||std::min(l.y0,l.y1)>n1)continue;
        const float x0=ox+sx*l.x0,y0=oy-sy*l.y0,x1=ox+sx*l.x1,y1=oy-sy*l.y1;
        if(x0>=xMin&&x0<=xMax&&x1>=xMin&&x1<=xMax&&y0>=yMin&&y0<=yMax&&y1>=yMin&&y1<=yMax){
          const long ax=lroundf(x0),ay=lroundf(y0),bx=lroundf(x1),by=lroundf(y1);
          for(int offset=-spread(l.kind);offset<=spread(l.kind);++offset)c.drawLine(ax,ay+offset,bx,by+offset,ink(l.kind));
        }else stroke(c,v,x0,y0,x1,y1,l.kind);
      }
    }
    return charted;
  }
};
// Remembers which site the kart was last seen at, so the no-GPS overview shows the right
// place after a restart. One stored byte, rewritten only when the kart moves to another site.
template<class Backend> struct HomeSite {
  Backend backend;int site=0;
  void load(){uint8_t stored=0;site=backend.read(stored)&&SiteMap::get(stored)?stored:0;}
  // Call with a fresh own position only. Returns true when the remembered site changed.
  bool seen(double lat,double lon){
    const int here=SiteMap::containing(lat,lon);
    if(here<0||here==site)return false;
    site=here;backend.write(uint8_t(here));return true;
  }
};
}
#ifdef ARDUINO
#include <Preferences.h>
namespace m5dash {
struct SiteNvs {
  bool read(uint8_t& value){Preferences p;if(!p.begin("m5site",true))return false;const bool found=p.isKey("home");if(found)value=p.getUChar("home",0);p.end();return found;}
  bool write(uint8_t value){Preferences p;if(!p.begin("m5site",false))return false;const bool ok=p.putUChar("home",value)==1;p.end();return ok;}
};
}
#endif
